*** Begin Patch
*** Add File: output/assets/styles.css
+:root{
+  --bg0:#0D1B2A;
+  --bg1:#0F2436;
+  --panel:#111F2E;
+  --panel2:#15263A;
+  --text:#E6EEF8;
+  --muted:#A7B4C6;
+  --muted2:#7E8CA3;
+  --border:rgba(255,255,255,.10);
+  --shadow:0 18px 50px rgba(0,0,0,.45);
+  --accent:#00B4D8;
+  --accent2:#0077B6;
+  --ok:#6CC24A;
+  --warn:#F6C177;
+
+  --radius:16px;
+  --radius2:22px;
+  --container:1180px;
+
+  --font: Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji","Segoe UI Emoji";
+}
+
+*{box-sizing:border-box}
+html{color-scheme:dark;scroll-behavior:smooth}
+body{
+  margin:0;
+  font-family:var(--font);
+  color:var(--text);
+  background:
+    radial-gradient(1100px 550px at 15% 0%, rgba(0,180,216,.17), transparent 55%),
+    radial-gradient(900px 500px at 85% 10%, rgba(0,119,182,.18), transparent 60%),
+    linear-gradient(180deg, var(--bg0), #0B1622 70%, #08111A);
+  line-height:1.55;
+}
+
+img,svg{max-width:100%;height:auto;display:block}
+a{color:inherit;text-decoration:none}
+
+.container{max-width:var(--container);margin:0 auto;padding:0 20px}
+
+.skip-link{
+  position:absolute;left:-999px;top:auto;width:1px;height:1px;overflow:hidden;
+}
+.skip-link:focus{
+  left:16px;top:12px;width:auto;height:auto;z-index:1000;
+  background:rgba(255,255,255,.08);border:1px solid var(--border);
+  padding:10px 12px;border-radius:12px;backdrop-filter: blur(10px);
+}
+
+/* Header */
+.site-header{
+  position:sticky;top:0;z-index:900;
+  backdrop-filter: blur(14px);
+  background: rgba(11, 22, 34, .62);
+  border-bottom:1px solid var(--border);
+}
+.nav{
+  display:flex;align-items:center;justify-content:space-between;
+  padding:14px 0;
+  gap:14px;
+}
+.brand{
+  display:flex;align-items:center;gap:12px;
+}
+.brand-mark{
+  width:38px;height:38px;border-radius:12px;
+  background:
+    radial-gradient(circle at 30% 25%, rgba(0,180,216,.9), rgba(0,180,216,.15) 48%, transparent 65%),
+    radial-gradient(circle at 80% 75%, rgba(108,194,74,.65), rgba(108,194,74,.10) 55%, transparent 70%),
+    linear-gradient(180deg, rgba(255,255,255,.10), rgba(255,255,255,.02));
+  border:1px solid rgba(255,255,255,.14);
+  box-shadow: 0 12px 24px rgba(0,0,0,.35);
+}
+.brand-title{font-weight:700;letter-spacing:.2px}
+.brand-sub{color:var(--muted);font-size:12px;margin-top:1px}
+
+.nav-links{
+  display:flex;align-items:center;gap:10px;
+}
+.nav-links a, .nav-links button{
+  font:inherit;
+  color:var(--text);
+}
+
+.nav-pill{
+  padding:10px 12px;
+  border-radius:999px;
+  border:1px solid transparent;
+  color:var(--muted);
+  transition: border-color .18s ease, background .18s ease, color .18s ease;
+}
+.nav-pill:hover{color:var(--text);border-color:rgba(255,255,255,.12);background:rgba(255,255,255,.04)}
+.nav-pill[aria-current="page"]{color:var(--text);border-color:rgba(0,180,216,.35);background:rgba(0,180,216,.08)}
+
+.cta{
+  display:inline-flex;align-items:center;justify-content:center;
+  gap:10px;
+  padding:12px 16px;
+  border-radius:999px;
+  border:1px solid rgba(0,180,216,.45);
+  background: linear-gradient(180deg, rgba(0,180,216,.22), rgba(0,119,182,.14));
+  box-shadow: 0 10px 26px rgba(0,180,216,.10);
+  transition: transform .12s ease, filter .12s ease, border-color .12s ease;
+}
+.cta:hover{transform:translateY(-1px);filter:saturate(1.05);border-color:rgba(0,180,216,.60)}
+.cta.secondary{
+  border:1px solid rgba(255,255,255,.14);
+  background: rgba(255,255,255,.05);
+  box-shadow:none;
+}
+
+.icon{
+  width:18px;height:18px;flex:0 0 auto;
+  fill:currentColor;opacity:.95
+}
+
+.menu-btn{
+  display:none;
+  border:1px solid rgba(255,255,255,.14);
+  background: rgba(255,255,255,.06);
+  color:var(--text);
+  padding:10px 12px;border-radius:14px;
+}
+
+.dropdown{position:relative}
+.dropdown > button{
+  background:transparent;
+  border:1px solid transparent;
+  padding:10px 12px;
+  border-radius:999px;
+  color:var(--muted);
+  cursor:pointer;
+  display:inline-flex;align-items:center;gap:8px;
+}
+.dropdown > button:hover{color:var(--text);border-color:rgba(255,255,255,.12);background:rgba(255,255,255,.04)}
+.dropdown-panel{
+  position:absolute;left:0;top:calc(100% + 10px);
+  min-width:260px;
+  border-radius:16px;
+  border:1px solid rgba(255,255,255,.12);
+  background: rgba(13, 27, 42, .94);
+  backdrop-filter: blur(14px);
+  box-shadow: var(--shadow);
+  padding:10px;
+  display:none;
+}
+.dropdown[data-open="true"] .dropdown-panel{display:block}
+.dropdown-item{
+  display:flex;align-items:flex-start;gap:12px;
+  padding:10px 12px;border-radius:14px;
+  color:var(--text);
+}
+.dropdown-item:hover{background:rgba(255,255,255,.06)}
+.dropdown-item small{display:block;color:var(--muted);margin-top:2px;line-height:1.3}
+
+/* Sections */
+.section{padding:72px 0}
+.section.compact{padding:54px 0}
+.eyebrow{color:rgba(0,180,216,.92);text-transform:uppercase;font-weight:700;letter-spacing:.12em;font-size:12px}
+.h1{font-size:clamp(34px, 4.8vw, 56px);line-height:1.05;margin:14px 0 12px}
+.h2{font-size:clamp(26px, 3.2vw, 40px);line-height:1.12;margin:10px 0 14px}
+.lead{font-size:clamp(16px, 1.2vw, 18px);color:var(--muted);max-width:72ch}
+
+.grid{display:grid;gap:18px}
+.grid.two{grid-template-columns:repeat(2, minmax(0,1fr))}
+.grid.three{grid-template-columns:repeat(3, minmax(0,1fr))}
+.grid.four{grid-template-columns:repeat(4, minmax(0,1fr))}
+
+.card{
+  border:1px solid rgba(255,255,255,.10);
+  background: linear-gradient(180deg, rgba(255,255,255,.06), rgba(255,255,255,.02));
+  border-radius:var(--radius);
+  box-shadow: 0 14px 40px rgba(0,0,0,.35);
+}
+.card.pad{padding:18px}
+.card.pad-lg{padding:22px}
+.card-title{font-weight:700;margin:2px 0 6px}
+.card-desc{color:var(--muted);margin:0}
+.chip{
+  display:inline-flex;align-items:center;gap:8px;
+  padding:7px 10px;border-radius:999px;
+  border:1px solid rgba(255,255,255,.12);
+  background: rgba(255,255,255,.04);
+  color:var(--muted);
+  font-size:12px;
+}
+
+.hero{
+  padding:64px 0 42px;
+}
+.hero .hero-shell{
+  display:grid;
+  grid-template-columns: 1.2fr .8fr;
+  gap:28px;
+  align-items:start;
+}
+
+.hero-panel{
+  border-radius:var(--radius2);
+  border:1px solid rgba(255,255,255,.11);
+  background:
+    radial-gradient(900px 480px at 12% 20%, rgba(0,180,216,.18), transparent 60%),
+    radial-gradient(700px 420px at 92% 30%, rgba(108,194,74,.12), transparent 55%),
+    linear-gradient(180deg, rgba(255,255,255,.06), rgba(255,255,255,.015));
+  box-shadow: var(--shadow);
+  padding:26px;
+}
+
+.hero-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:18px}
+
+.featured{
+  display:flex;align-items:center;justify-content:space-between;
+  gap:14px;
+  padding:16px 18px;
+  border-radius:18px;
+  border:1px solid rgba(0,180,216,.30);
+  background: linear-gradient(90deg, rgba(0,180,216,.12), rgba(0,119,182,.10));
+}
+.featured strong{display:block;margin-bottom:3px}
+.featured small{color:var(--muted)}
+
+/* Tabs */
+.tabs{
+  display:flex;flex-wrap:wrap;
+  gap:10px;
+  padding:10px;
+  border-radius:18px;
+  border:1px solid rgba(255,255,255,.10);
+  background: rgba(255,255,255,.03);
+}
+.tab{
+  border:1px solid rgba(255,255,255,.10);
+  background: rgba(255,255,255,.04);
+  color:var(--muted);
+  padding:10px 12px;
+  border-radius:999px;
+  cursor:pointer;
+  transition: transform .10s ease, border-color .18s ease, background .18s ease, color .18s ease;
+}
+.tab:hover{transform:translateY(-1px);color:var(--text);border-color:rgba(255,255,255,.16)}
+.tab[aria-selected="true"]{
+  color:var(--text);
+  border-color:rgba(0,180,216,.55);
+  background: rgba(0,180,216,.10);
+}
+.tabpanels{margin-top:14px}
+.tabpanel{
+  display:none;
+  padding:18px;
+  border-radius:18px;
+  border:1px solid rgba(255,255,255,.10);
+  background: rgba(17,31,46,.60);
+}
+.tabpanel[hidden]{display:none}
+.tabpanel.active{display:block;animation:fadeSlide .22s ease}
+@keyframes fadeSlide{from{opacity:.0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}
+
+/* Diagrams */
+.diagram{
+  border-radius:22px;
+  border:1px solid rgba(255,255,255,.10);
+  background:
+    radial-gradient(900px 520px at 30% 15%, rgba(0,180,216,.16), transparent 60%),
+    radial-gradient(900px 520px at 70% 25%, rgba(0,119,182,.14), transparent 62%),
+    linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,.02));
+  box-shadow: var(--shadow);
+  padding:18px;
+}
+.diagram-title{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}
+.diagram-title h3{margin:0;font-size:16px}
+.diagram-sub{color:var(--muted);font-size:13px}
+
+/* Use cases */
+.usecase-grid .card{cursor:pointer}
+.usecase-grid .card:hover{border-color:rgba(0,180,216,.35)}
+
+/* Benefits list */
+.list{margin:0;padding:0;list-style:none}
+.list li{display:flex;gap:12px;align-items:flex-start;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.06)}
+.list li:last-child{border-bottom:none}
+.check{
+  width:22px;height:22px;border-radius:7px;
+  background: rgba(108,194,74,.14);
+  border:1px solid rgba(108,194,74,.38);
+  display:grid;place-items:center;
+  flex:0 0 auto;
+}
+.check svg{width:14px;height:14px;fill:var(--ok)}
+
+/* Stats rings */
+.stats{display:grid;grid-template-columns:repeat(3, minmax(0,1fr));gap:16px}
+.stat{
+  padding:18px;
+  border-radius:18px;
+  border:1px solid rgba(255,255,255,.10);
+  background: rgba(17,31,46,.55);
+}
+.stat-top{display:flex;align-items:center;gap:14px}
+.ring{
+  width:64px;height:64px;border-radius:50%;
+  background:
+    conic-gradient(from 210deg, rgba(0,180,216,.95) var(--p), rgba(255,255,255,.10) 0);
+  position:relative;
+  border:1px solid rgba(255,255,255,.12);
+}
+.ring::after{
+  content:"";
+  position:absolute;inset:7px;
+  border-radius:50%;
+  background: rgba(13,27,42,.86);
+  border:1px solid rgba(255,255,255,.08);
+}
+.ring-value{position:absolute;inset:0;display:grid;place-items:center;font-weight:800;font-size:18px;z-index:1}
+.stat-label{font-weight:700;margin:0}
+.stat-desc{margin:6px 0 0;color:var(--muted)}
+
+/* Timeline */
+.timeline{display:grid;gap:14px}
+.timeline-item{padding:16px;border-radius:18px;border:1px solid rgba(255,255,255,.10);background: rgba(17,31,46,.55)}
+.timeline-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}
+.timeline-duration{font-weight:900;letter-spacing:.08em;color:rgba(0,180,216,.92)}
+.timeline-desc{color:var(--muted);margin:4px 0 0}
+.progress{height:10px;border-radius:999px;background: rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.08);overflow:hidden;margin-top:12px}
+.progress > div{height:100%;width:var(--w);background: linear-gradient(90deg, rgba(0,180,216,.75), rgba(0,119,182,.65));}
+
+/* Accordion */
+.accordion{display:grid;gap:10px}
+.acc-item{border-radius:18px;border:1px solid rgba(255,255,255,.10);background: rgba(17,31,46,.55);overflow:hidden}
+.acc-btn{
+  width:100%;
+  text-align:left;
+  display:flex;align-items:center;justify-content:space-between;gap:12px;
+  padding:14px 16px;
+  background:transparent;border:none;color:var(--text);
+  font:inherit;cursor:pointer;
+}
+.acc-btn span{font-weight:800}
+.acc-panel{padding:0 16px 14px;color:var(--muted);display:none}
+.acc-item[data-open="true"] .acc-panel{display:block;animation:fadeSlide .18s ease}
+.acc-icon{width:22px;height:22px;border-radius:999px;border:1px solid rgba(255,255,255,.14);display:grid;place-items:center;color:var(--muted)}
+.acc-item[data-open="true"] .acc-icon{border-color:rgba(0,180,216,.45);color:var(--text);background:rgba(0,180,216,.08)}
+
+/* Carousel */
+.carousel{
+  border-radius:22px;
+  border:1px solid rgba(255,255,255,.10);
+  background: rgba(17,31,46,.55);
+  padding:18px;
+}
+.carousel-track{
+  display:flex;
+  gap:16px;
+  overflow:hidden;
+  scroll-behavior:smooth;
+}
+.testimonial{min-width:100%;padding:18px;border-radius:18px;border:1px solid rgba(255,255,255,.10);background: rgba(255,255,255,.03)}
+.quote{margin:0;color:var(--text);font-size:16px}
+.by{margin:10px 0 0;color:var(--muted)}
+.dots{display:flex;gap:10px;justify-content:center;margin-top:14px}
+.dot{width:10px;height:10px;border-radius:999px;border:1px solid rgba(255,255,255,.20);background: rgba(255,255,255,.08);cursor:pointer}
+.dot[aria-current="true"]{background: rgba(0,180,216,.70);border-color:rgba(0,180,216,.70)}
+
+/* Forms */
+form{margin:0}
+.form{
+  display:grid;
+  gap:14px;
+}
+.field{display:grid;gap:6px}
+.field label{font-size:13px;color:var(--muted)}
+.field input,.field select,.field textarea{
+  width:100%;
+  border-radius:14px;
+  border:1px solid rgba(255,255,255,.12);
+  background: rgba(10,18,28,.55);
+  color:var(--text);
+  padding:12px 12px;
+  font:inherit;
+  outline:none;
+}
+.field textarea{min-height:120px;resize:vertical}
+.field input:focus,.field select:focus,.field textarea:focus{border-color:rgba(0,180,216,.55);box-shadow: 0 0 0 4px rgba(0,180,216,.10)}
+.error{color:#FFB4B4;font-size:12px;display:none}
+.field[data-invalid="true"] .error{display:block}
+.field[data-invalid="true"] input,.field[data-invalid="true"] select,.field[data-invalid="true"] textarea{border-color:rgba(255,100,120,.55)}
+
+.toast{
+  display:none;
+  margin-top:14px;
+  padding:12px 14px;
+  border-radius:14px;
+  border:1px solid rgba(108,194,74,.35);
+  background: rgba(108,194,74,.10);
+  color: rgba(231,255,231,.95);
+}
+.toast.show{display:block}
+
+/* Footer */
+footer{
+  border-top:1px solid rgba(255,255,255,.10);
+  background: rgba(6,12,18,.55);
+}
+.footer-grid{display:grid;grid-template-columns:1.2fr repeat(4, minmax(0,1fr));gap:18px;padding:34px 0}
+.footer-col h4{margin:0 0 10px;font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:rgba(255,255,255,.78)}
+.footer-col a{display:block;color:var(--muted);padding:6px 0}
+.footer-col a:hover{color:var(--text)}
+.footer-bottom{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px 0;border-top:1px solid rgba(255,255,255,.08);color:var(--muted);font-size:12px}
+
+/* Cookie banner */
+.cookie{
+  position:fixed;left:14px;right:14px;bottom:14px;z-index:999;
+  border-radius:18px;
+  border:1px solid rgba(255,255,255,.12);
+  background: rgba(13,27,42,.92);
+  backdrop-filter: blur(14px);
+  box-shadow: var(--shadow);
+  padding:14px;
+  display:none;
+}
+.cookie.show{display:block;animation:fadeSlide .22s ease}
+.cookie-inner{display:flex;align-items:flex-start;justify-content:space-between;gap:14px}
+.cookie p{margin:0;color:var(--muted)}
+.cookie-actions{display:flex;gap:10px;flex-wrap:wrap}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero .hero-shell{grid-template-columns:1fr}
+  .footer-grid{grid-template-columns:1fr 1fr}
+  .stats{grid-template-columns:1fr}
+  .grid.four{grid-template-columns:repeat(2, minmax(0,1fr))}
+}
+@media (max-width: 760px){
+  .nav-links{display:none}
+  .menu-btn{display:inline-flex}
+  .mobile-panel{display:none}
+  .mobile-panel.show{display:block}
+  .mobile-panel{padding:10px 0 16px}
+  .mobile-panel a, .mobile-panel button{
+    display:block;width:100%;text-align:left;
+    padding:12px 12px;border-radius:14px;
+    border:1px solid rgba(255,255,255,.10);
+    background: rgba(255,255,255,.04);
+    margin-top:10px;color:var(--text);
+  }
+  .mobile-panel a:hover, .mobile-panel button:hover{background:rgba(255,255,255,.06)}
+  .grid.three{grid-template-columns:1fr}
+  .grid.two{grid-template-columns:1fr}
+}
+
*** End Patch
PATCH

